function identifiedReserveCategorySql(alias:string,time:'08:00'|'18:00'){
 const binding=alias+'.binding',tail=time==='08:00'?outroTemplateCatalog.variants.dark.sha256:outroTemplateCatalog.variants.light.sha256,legacyTail=time==='08:00'?legacyOutroTemplateCatalog.variants.dark.sha256:legacyOutroTemplateCatalog.variants.light.sha256;
 const pinned="tm.id=json_extract("+binding+",'$.video_milestone_id') AND tm.artifact_hash=json_extract("+binding+",'$.video_artifact_hash')";
 return "(json_extract("+binding+",'$.template_publishing_slot.time')='"+time+"' OR (json_extract("+binding+",'$.template_publishing_slot') IS NULL AND EXISTS(SELECT 1 FROM production_milestones tm WHERE "+pinned+" AND json_extract(tm.artifact,'$.qa.outro_sha256') IN ('"+tail+"','"+legacyTail+"'))))";
}
function reserveCategorySql(alias:string,time:'08:00'|'18:00'){
 const binding=alias+'.binding',pinned="tm.id=json_extract("+binding+",'$.video_milestone_id') AND tm.artifact_hash=json_extract("+binding+",'$.video_artifact_hash')";
 // Historical unclassified packages retain their existing FIFO behavior. This
 // eligibility fallback never labels their unknown actual color in the UI.
 return '('+identifiedReserveCategorySql(alias,time)+" OR (json_extract("+binding+",'$.template_publishing_slot') IS NULL AND NOT EXISTS(SELECT 1 FROM production_milestones tm WHERE "+pinned+" AND json_extract(tm.artifact,'$.qa.outro_sha256') IN ('"+outroTemplateCatalog.variants.dark.sha256+"','"+outroTemplateCatalog.variants.light.sha256+"','"+legacyOutroTemplateCatalog.variants.dark.sha256+"','"+legacyOutroTemplateCatalog.variants.light.sha256+"'))))";
}
