function decoded<T>(value:unknown):T{try{return JSON.parse(String(value)) as T;}catch{throw new ProductionError('保存的发布绑定无效',409);}}
function receipt(value:unknown):string|null {
 if(value===undefined||value===null)return null;
 const walk=(v:unknown,depth=0):unknown=>{if(depth>8)throw new ProductionError('回执层级过深',400);if(Array.isArray(v))return v.slice(0,100).map(x=>walk(x,depth+1));if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).filter(([k])=>!/(?:^|_)(?:token|cookie|password|secret|authorization|api_key)(?:$|_)/i.test(k)).map(([k,x])=>[k,walk(x,depth+1)]));return v;};
 const out=JSON.stringify(walk(value));if(out.length>64000)throw new ProductionError('回执过大，请引用私有证据身份',400);return out;
}
