async function stagePreparedSlot(owner:string,preparationId:string,adapter:PublishingAdapter,continuationPlatforms?:PublishingPlatform[]){
 if(!adapter.preparePublish)throw new ProductionError('本适配器不支持无外发的提前就位',409);
 const at=stamp(adapter),{preparation:prep,raw}=await storedPreparation(owner,preparationId),pkg=await readFrozenPublishingPackage(owner,prep.package_id),works=await preparationWorks(owner,prep.id),p=await plan(owner);


 const actual=await connections(owner,adapter),eligible=new Set<string>(),reasons:Record<string,string>={};
 for(const w of works){
  if(continuationPlatforms&&!continuationPlatforms.includes(w.platform))continue;
  if(w.state!=='prepared'||w.phase!=='draft_saved'||!w.draft_locator||!w.prepared_at)continue;
  try{await assertPublishingPreparationCurrent(owner,w,at,{record_only:true});eligible.add(w.platform);}catch(e){if(!(e instanceof ProductionError))throw e;reasons[w.platform]=e.message;}
 }
 const c=actual.map(a=>{const w=works.find(w=>w.platform===a.platform),ready=eligible.has(a.platform),native=a.platform==='wechat_channels';return {...a,can_publish:!native&&ready&&a.can_publish&&a.account_id===w?.account_id,reason:reasons[a.platform]||(!ready?'本平台原草稿尚未准备完成':native?'视频号沿原手机执行对话接续':a.reason)};});
 if(!c.some(a=>a.can_publish)&&!eligible.has('wechat_channels'))return {...await readPublishingPreparation(owner,{preparation_id:prep.id}),no_submission:true,no_external_action:true,reason:'暂无可就位平台，其他平台的准备不受阻塞',platform_reasons:reasons};
 const first=await release(owner,prep.release_id),prior=await db().prepare('SELECT * FROM publishing_slots WHERE id=? AND owner_id=?').bind(prep.slot_id,owner).first<Slot>();
 if(!prior?.release_id)await assignSlot(owner,first,prep.slot_id,prep.scheduled_at,p,c,at,prior||undefined,true);
 else if(prior.release_id!==prep.release_id)throw new ProductionError('本场已绑定另一包，不换片',409);
 const assigned=await db().prepare('SELECT * FROM publishing_slots WHERE id=? AND owner_id=?').bind(prep.slot_id,owner).first<Slot>();
 if(assigned?.release_id!==prep.release_id)throw new ProductionError('本场就位领取未确认，只读回查原状态',409);
 const next={...prep,state:'claimed' as const,updated_at:at},pointer=await db().prepare('SELECT value FROM app_state WHERE key=?').bind(slotPreparationKey(owner,prep.slot_id)).first<{value:string}>();
 if(!pointer||decoded<PublishingSlotPreparation>(pointer.value).id!==prep.id)throw new ProductionError('原准备包已变化',409);
 await db().batch([db().prepare('UPDATE app_state SET value=? WHERE key=? AND value=?').bind(JSON.stringify(next),preparationKey(prep.id),raw),db().prepare('UPDATE app_state SET value=? WHERE key=? AND value=?').bind(JSON.stringify(next),slotPreparationKey(owner,prep.slot_id),pointer.value)]);
 await resumeUnstartedTargets(owner,assigned,p,c,at);
 const pending=(await db().prepare("SELECT * FROM publishing_posts WHERE owner_id=? AND slot_id=? AND status='pending'").bind(owner,prep.slot_id).all()).results as Post[];
 await Promise.all(pending.filter(row=>c.find(a=>a.platform===row.platform)?.can_publish).map(row=>sendPost(owner,row,adapter,true)));
 const prepared=await readPublishingPreparation(owner,{preparation_id:prep.id}),queued=(await db().prepare("SELECT value FROM app_state WHERE key LIKE 'publishing_browser_work_v2:%' AND json_extract(value,'$.owner_id')=? AND json_extract(value,'$.kind')='publish' AND json_extract(value,'$.input.slot_id')=?").bind(owner,prep.slot_id).all<{value:string}>()).results.map(r=>decoded<Record<string,unknown>>(r.value));
 return {preparation:prepared.preparation,package_id:pkg.id,staged:true,no_external_action:true,publish_allowed:false,submission_window:prep.submission_window,platform_reasons:reasons,publish_work:queued.map(w=>({id:w.id,platform:w.platform,state:w.state,phase:w.phase,...(w.preparation as Record<string,unknown>||{})})),next_action:'各平台claim原publish_work并在已恢复页面checkpoint armed；真实时钟到点后只点一次发布，全部提交后再取ID和回填'};
}
export async function armPreparedPublishingSlot(owner:string,b:Record<string,unknown>,adapter:PublishingAdapter){
 if(Object.keys(b).some(k=>!['action','preparation_id'].includes(k)))throw new ProductionError('提前就位只接受原preparation_id，不接受时钟、强制或换片',400);
 return stagePreparedSlot(owner,text(b.preparation_id,100),adapter);
}

export async function runPreparedPublishingTick(owner:string,adapter:PublishingAdapter,b:Record<string,unknown>={}){
 if(Object.keys(b).some(k=>!['action','preparation_id'].includes(k)))throw new ProductionError('只接受原准备任务，不接受额外时钟或换片',400);
 text(owner,500);const at=stamp(adapter),p=await plan(owner),selected=b.preparation_id!==undefined?(await storedPreparation(owner,text(b.preparation_id,100))).preparation:null;
 if(!p.enabled)throw new ProductionError('发布计划已暂停',409);
 const due=selected?.scheduled_at||publishingSchedule(at).today.filter(s=>Date.parse(s)<=Date.parse(at)).at(-1),start=selected?.submission_window?.start||due;
 if(!due||!start||!Number.isFinite(Date.parse(start))||Date.parse(at)<Date.parse(start))return {...await readPublishingPreparation(owner,selected?{preparation_id:selected.id}:{}),no_submission:true,reason:'尚未到计划发布时间；准备可随时继续'};
 const slotId=selected?.slot_id||'ps_'+await hash(owner+'\n'+due),pointer=await db().prepare('SELECT value FROM app_state WHERE key=?').bind(slotPreparationKey(owner,slotId)).first<{value:string}>();
 if(!pointer)return {preparation:null,package:null,work:[],no_submission:true,reason:'本场尚无准备包'};
 const prep=decoded<PublishingSlotPreparation>(pointer.value);if(selected&&prep.id!==selected.id)throw new ProductionError('本场准备包已变化，请读取当前原草稿',409);
 const pkg=await readFrozenPublishingPackage(owner,prep.package_id),works=await preparationWorks(owner,prep.id),first=await release(owner,prep.release_id);
 if(!works.length)return {...await readPublishingPreparation(owner,{preparation_id:prep.id}),no_submission:true,reason:'本场尚无准备任务'};
 await assertPublishingPreparationCurrent(owner,works[0],at);

 const actual=await connections(owner,adapter),c=actual.map(a=>{const w=works.find(w=>w.platform===a.platform),native=a.platform==='wechat_channels',prepared=w?.phase==='draft_saved'&&w.state==='prepared'&&w.account_id===a.account_id;return {...a,can_publish:!native&&a.can_publish&&prepared,reason:native?'视频号由同一冻结包的手机原生准备任务继续，不操作被阻断网页':!prepared?'当前冻结包尚无真实已保存草稿，保留同一任务等待准备':a.reason};}),prior=await db().prepare('SELECT * FROM publishing_slots WHERE id=? AND owner_id=?').bind(slotId,owner).first<Slot>();
 if(!prior?.release_id){const fifo=await db().prepare(`SELECT id FROM publishing_reserve WHERE owner_id=? AND status='ready' AND ${reserveCategorySql('publishing_reserve',publishingTime(due))} ORDER BY approved_at,id LIMIT 1`).bind(owner).first<{id:string}>();if(fifo?.id!==first.id)throw new ProductionError('本场FIFO已变化，保留原准备包而不临时换片',409);await assignSlot(owner,first,slotId,due,p,c,at,prior||undefined);}else if(prior.release_id!==first.id)throw new ProductionError('本场已有另一唯一领取，禁止重复',409);
 const assigned=await db().prepare('SELECT * FROM publishing_slots WHERE id=? AND owner_id=?').bind(slotId,owner).first<Slot>();if(assigned?.release_id!==first.id)throw new ProductionError('本场领取未确认，先读回原状态',409);const next={...prep,state:'claimed' as const,updated_at:at};await db().batch([db().prepare('UPDATE app_state SET value=? WHERE key=? AND value=?').bind(JSON.stringify(next),preparationKey(prep.id),JSON.stringify(prep)),db().prepare('UPDATE app_state SET value=? WHERE key=? AND value=?').bind(JSON.stringify(next),slotPreparationKey(owner,slotId),pointer.value)]);await resumeUnstartedTargets(owner,assigned,p,c,at);const pending=(await db().prepare("SELECT * FROM publishing_posts WHERE owner_id=? AND slot_id=? AND status='pending'").bind(owner,slotId).all()).results as Post[];await Promise.all(pending.filter(r=>c.find(x=>x.platform===r.platform)?.can_publish).map(row=>sendPost(owner,row,adapter)));await finishSlot(owner,slotId,stamp(adapter));return {...await readPublishingPreparation(owner,{preparation_id:prep.id}),no_submission:false};
}
/** Durable result reconciliation has no scheduling, reserve selection, uploads or new posts. */
export async function runPublishingReconciliation(owner:string,adapter:PublishingAdapter){text(owner,500);const p=await plan(owner);if(!p.enabled||!p.authorization_id)throw new ProductionError('当前发布计划未启用，保留回执等待恢复',409);await reconcilePosts(owner,adapter);return {dashboard:await readPublishingDashboard(owner,adapter),no_external_action:true};}
